/* Native port runtime interface (see docs/PORT.md).  Only port/ code includes this. */
#ifndef PORT_RUNTIME_H
#define PORT_RUNTIME_H

typedef unsigned int u32p;
typedef struct { u32p addr; void *fn; const char *name; } PortFunc;

/* generated by port/tools/gen_port.py */
extern const PortFunc port_funcmap[];
extern const int port_funcmap_count;
/* generated by gen_port.py link (thunks.S): native function per retail unit address; Psy-Q unit addresses */
typedef struct { u32p addr; void *fn; } PortLib;
extern const PortLib port_libmap[];
extern const int port_libmap_count;
extern const u32p port_libaddrs[];
extern const int port_libaddrs_count;
int port_is_lib_addr(u32p addr);
/* MIPS interpreter (runtime/mips_interp.c) for code without C */
extern u32p port_mips_pending;
extern int port_interp;          /* 0: --no-interp (stub instead) */
u32p port_mips_entry(u32p, u32p, u32p, u32p, u32p, u32p, u32p, u32p);
int port_mips_calls(void);
/* asm-only MAIN0 functions translated by hand (port/runtime/main0_handwritten.c), {0} terminated */
extern const PortFunc port_extra_funcs[];
/* overlay set (SYSTEM overlays at 0x800E8028): resident while the header word at 0x800E8028 equals id */
typedef struct { u32p id; u32p addr; void *fn; const char *name; } PortOvlFunc;
typedef struct { u32p id; const char *name; } PortOvl;
extern const PortOvlFunc port_ovlmap[];
extern const int port_ovlmap_count;
extern const PortOvl port_ovls[];
#define PORT_OVL_BASE 0x800E8028u
#define PORT_OVL_END  0x80140000u
#define PORT_AREA_OWN_CODE 0x80115EA4u   /* X0nn: first per-area function (the 188 KB before it are shared) */
const char *port_resident_overlay(void);

/* PS1 address space emulated in the process: RAM (2 MB, mirrored nowhere) and the scratchpad + I/O page */
#define PSX_RAM_BASE   0x80000000u
#define PSX_RAM_SIZE   0x00200000u
#define PSX_SPAD_BASE  0x1F800000u
#define PSX_SPAD_SIZE  0x00004000u   /* scratchpad 1 KB + hardware registers 0x1F801000.. as plain memory */

/* libc subset (freestanding build: no host libc in the i386 prototype) */
void port_puts(const char *s);
void port_printf(const char *fmt, ...);
int port_vsnprintf(char *buf, int n, const char *fmt, __builtin_va_list ap);
void port_exit(int code) __attribute__((noreturn));
void port_fatal(const char *fmt, ...) __attribute__((noreturn));

/* host file access */
int port_open(const char *path);
int port_read(int fd, void *buf, int n);
int port_pread(int fd, void *buf, int n, long long off);
void port_close(int fd);
int port_create(const char *path);              /* write-only, truncates */
int port_write(int fd, const void *buf, int n);
int port_mkdir(const char *path);
long long port_filesize(int fd);

/* time */
unsigned long long port_time_us(void);
void port_sleep_us(unsigned long long us);

/* call resolution: native function for a retail code address (current overlay first) */
void *port_lookup(u32p addr);
void *port_resolve_call(u32p addr, const char *name);
void port_stub(const char *name, u32p addr);

/* cooperative threads (Psy-Q OpenTh/ChangeTh) */
int port_thread_open(void *fn);
void port_thread_change(int handle);
void port_thread_close(int handle);

/* frame pacing / vblank */
void port_vblank(void);          /* one emulated vertical blank: runs the game's VSync event handlers */
extern int port_frame;
extern int port_max_frames;      /* stop after this many vblanks (0 = no limit) */
extern int port_verbose;

/* CD image */
int port_cd_open(const char *path);
int port_cd_read_sectors(int lba, int count, void *dst, int sector_bytes);

/* GPU (shims/gpu.c): software rasteriser into emulated VRAM, frame dumps */
extern const char *port_dump_dir;    /* --dump-frames DIR: write the displayed frame as PNG */
extern int port_dump_every;          /* --dump-every N (default 10) */
extern int port_dump_vram;           /* --dump-vram: also write the whole 1024x512 VRAM */
void port_gpu_vblank(void);
#endif
